      function formatSettingsDate(value) {
        if (!value) {
          return "Unavailable";
        }

        const date = new Date(value);
        if (Number.isNaN(date.getTime())) {
          return "Unavailable";
        }

        return date.toLocaleDateString("en-US", {
          month: "short",
          day: "numeric",
          year: "numeric",
        });
      }

      function formatSettingsDateTime(value) {
        if (!value) {
          return "Unavailable";
        }

        const date = new Date(value);
        if (Number.isNaN(date.getTime())) {
          return "Unavailable";
        }

        return date.toLocaleString("en-US", {
          month: "short",
          day: "numeric",
          year: "numeric",
          hour: "numeric",
          minute: "2-digit",
        });
      }

      function normalizeSettingsLocalRunnerListPayload(data, key) {
        if (Array.isArray(data?.data)) {
          return data.data;
        }
        if (Array.isArray(data?.[key])) {
          return data[key];
        }
        return Array.isArray(data) ? data : [];
      }

      function normalizeSettingsRuntimeTarget(target) {
        const source = target && typeof target === "object" && !Array.isArray(target) ? target : {};
        const kind = ["cloud", "local_runner", "fully_local"].includes(source.kind) ? source.kind : "";
        if (!kind) {
          return null;
        }
        const status = ["available", "disabled", "planned", "unavailable"].includes(source.status)
          ? source.status
          : "unavailable";
        return {
          kind,
          label: normalizeSettingsLocalRunnerText(source.label, kind === "cloud" ? "Cloud Runtime" : kind === "local_runner" ? "Local Runner" : "Fully Local"),
          status,
          default: Boolean(source.default),
          description: normalizeSettingsLocalRunnerText(source.description),
          deviceCount: Number.isFinite(Number(source.deviceCount)) ? Number(source.deviceCount) : 0,
          onlineDeviceCount: Number.isFinite(Number(source.onlineDeviceCount)) ? Number(source.onlineDeviceCount) : 0,
          bindingCount: Number.isFinite(Number(source.bindingCount)) ? Number(source.bindingCount) : 0,
          bridgeLocalBindingCount: Number.isFinite(Number(source.bridgeLocalBindingCount)) ? Number(source.bridgeLocalBindingCount) : 0,
        };
      }

      function normalizeSettingsRuntimeTargetsPayload(data) {
        return normalizeSettingsLocalRunnerListPayload(data, "runtimeTargets")
          .map(normalizeSettingsRuntimeTarget)
          .filter(Boolean);
      }

      function normalizeSettingsLocalRunnerText(value, fallback = "") {
        return typeof value === "string" && value.trim() ? value.trim() : fallback;
      }

      function normalizeSettingsLocalRunnerDevice(device) {
        const source = device && typeof device === "object" && !Array.isArray(device) ? device : {};
        const id = normalizeSettingsLocalRunnerText(source.id || source.deviceId);
        if (!id) {
          return null;
        }

        const capabilities = source.capabilities && typeof source.capabilities === "object" && !Array.isArray(source.capabilities)
          ? source.capabilities
          : {};
        return {
          id,
          name: normalizeSettingsLocalRunnerText(source.name, normalizeSettingsLocalRunnerText(source.hostname, "Local runner")),
          platform: normalizeSettingsLocalRunnerText(source.platform, "Unknown platform"),
          hostname: normalizeSettingsLocalRunnerText(source.hostname),
          appVersion: normalizeSettingsLocalRunnerText(source.appVersion),
          daemonVersion: normalizeSettingsLocalRunnerText(source.daemonVersion),
          status: source.status === "online" ? "online" : "offline",
          lastSeenAt: normalizeSettingsLocalRunnerText(source.lastSeenAt),
          capabilities,
        };
      }

      function normalizeSettingsWorkspaceBinding(binding) {
        const source = binding && typeof binding === "object" && !Array.isArray(binding) ? binding : {};
        const id = normalizeSettingsLocalRunnerText(source.id || source.workspaceBindingId);
        const deviceId = normalizeSettingsLocalRunnerText(source.deviceId);
        if (!id || !deviceId) {
          return null;
        }
        return {
          id,
          deviceId,
          environmentId: normalizeSettingsLocalRunnerText(source.environmentId),
          projectId: normalizeSettingsLocalRunnerText(source.projectId),
          name: normalizeSettingsLocalRunnerText(source.name),
          localPath: normalizeSettingsLocalRunnerText(source.localPath),
          syncRoot: normalizeSettingsLocalRunnerText(source.syncRoot),
          syncMode: normalizeSettingsLocalRunnerText(source.syncMode, "manual"),
          executionMode: normalizeSettingsLocalRunnerText(source.executionMode, "legacy_remote"),
        };
      }

      function getSettingsLocalRuntimeCapabilities(device) {
        const capabilities = device?.capabilities && typeof device.capabilities === "object" && !Array.isArray(device.capabilities)
          ? device.capabilities
          : {};
        return capabilities.localRuntime && typeof capabilities.localRuntime === "object" && !Array.isArray(capabilities.localRuntime)
          ? capabilities.localRuntime
          : {};
      }

      function formatSettingsLocalRunnerRuntimeStatus(value) {
        switch (String(value || "").trim()) {
          case "available":
            return "Available";
          case "planned":
            return "Planned";
          case "disabled":
            return "Disabled";
          case "unavailable":
            return "Unavailable";
          default:
            return "Unknown";
        }
      }

      function formatSettingsLocalRunnerNumber(value, suffix = "") {
        const numericValue = Number(value);
        if (!Number.isFinite(numericValue)) {
          return "Unknown";
        }
        const rounded = Math.round(numericValue * 10) / 10;
        return String(rounded).replace(/\.0$/, "") + suffix;
      }

      function formatSettingsLocalRunnerDateTime(value) {
        const normalizedValue = normalizeSettingsLocalRunnerText(value);
        if (!normalizedValue) {
          return "Never";
        }
        const date = new Date(normalizedValue);
        if (Number.isNaN(date.getTime())) {
          return "Never";
        }
        return date.toLocaleString("en-US", {
          month: "short",
          day: "numeric",
          hour: "numeric",
          minute: "2-digit",
        });
      }

      function formatSettingsLocalRunnerToolchain(toolchain) {
        const source = toolchain && typeof toolchain === "object" && !Array.isArray(toolchain) ? toolchain : {};
        const activeTools = [
          source.docker ? "Docker" : "",
          source.podman ? "Podman" : "",
          source.ollama ? "Ollama" : "",
          source.git ? "Git" : "",
        ].filter(Boolean);
        return activeTools.length > 0 ? activeTools.join(", ") : "No local tools detected";
      }

      function getSettingsApiKeyScopeLabel(permissions) {
        const items = Array.isArray(permissions) ? permissions : [];
        for (const preset of Object.values(SETTINGS_API_KEY_SCOPE_PRESETS)) {
          if (
            preset.permissions.length === items.length &&
            preset.permissions.every((permission) => items.includes(permission))
          ) {
            return preset.label;
          }
        }
        return items.length ? "Custom" : "Default";
      }

      function isSettingsSystemManagedKey(apiKeyRecord) {
        const metadata = apiKeyRecord?.metadata && typeof apiKeyRecord.metadata === "object" && !Array.isArray(apiKeyRecord.metadata)
          ? apiKeyRecord.metadata
          : {};
        return metadata.isDefault === true || typeof metadata.createdBy === "string" && metadata.createdBy.includes("provisioner");
      }

      function getSettingsTriggerSourceMeta(source) {
        switch (String(source || "").trim().toLowerCase()) {
          case "github":
            return {
              label: "GitHub",
              icon: GitCommitHorizontal,
            };
          case "gitlab":
            return {
              label: "GitLab",
              icon: GitCommitHorizontal,
            };
          case "slack":
            return {
              label: "Slack",
              icon: MessageCircle,
            };
          default:
            return {
              label: "Webhook",
              icon: Webhook,
            };
        }
      }

      function getSettingsTriggerActionLabel(action) {
        const actionType = String(action?.type || "").trim().toLowerCase();
        if (actionType === "comment_pull_request") {
          return "Comment on PR";
        }
        if (actionType === "comment_merge_request") {
          return "Comment on MR";
        }
        return "Start thread";
      }

      function isSettingsTriggerActionSupportedForSource(source, actionType) {
        const normalizedSource = String(source || "").trim().toLowerCase();
        const normalizedActionType = String(actionType || "").trim().toLowerCase();
        if (normalizedActionType === "comment_pull_request") {
          return normalizedSource === "github";
        }
        if (normalizedActionType === "comment_merge_request") {
          return normalizedSource === "gitlab";
        }
        return true;
      }

      function getSettingsTriggerDefaultEvent(source, actionType) {
        const normalizedSource = String(source || "").trim().toLowerCase();
        const normalizedActionType = String(actionType || "").trim().toLowerCase();
        if (normalizedSource === "github") {
          return normalizedActionType === "comment_pull_request" ? "pull_request" : "push";
        }
        if (normalizedSource === "gitlab") {
          return normalizedActionType === "comment_merge_request" ? "Merge Request Hook" : "Push Hook";
        }
        return "";
      }

      function getSettingsTriggerEventOptions(source, actionType) {
        const normalizedSource = String(source || "").trim().toLowerCase();
        const normalizedActionType = String(actionType || "").trim().toLowerCase();
        if (normalizedSource === "github") {
          return normalizedActionType === "comment_pull_request"
            ? SETTINGS_GITHUB_PULL_REQUEST_ACTION_EVENTS
            : SETTINGS_GITHUB_EVENTS;
        }
        if (normalizedSource === "gitlab") {
          return normalizedActionType === "comment_merge_request"
            ? SETTINGS_GITLAB_MERGE_REQUEST_ACTION_EVENTS
            : SETTINGS_GITLAB_EVENTS;
        }
        return [];
      }

      function getSettingsTriggerPromptPlaceholder(source, actionType) {
        const normalizedSource = String(source || "").trim().toLowerCase();
        const normalizedActionType = String(actionType || "").trim().toLowerCase();
        if (normalizedActionType === "comment_pull_request") {
          return "Review the pull request changes and write a concise, helpful GitHub comment.";
        }
        if (normalizedActionType === "comment_merge_request") {
          return "Review the merge request changes and write a concise, helpful GitLab comment.";
        }
        if (normalizedSource === "gitlab") {
          return "Inspect the GitLab event, pull the latest changes if needed, and summarize what happened.";
        }
        return "Pull the latest changes, inspect the webhook payload, and summarize what happened.";
      }

      function mapFirebaseAuthErrorMessage(code, fallbackMessage) {
        const normalized = String(code || "").trim().toUpperCase();
        if (!normalized) {
          return fallbackMessage;
        }
        if (normalized === "INVALID_LOGIN_CREDENTIALS" || normalized === "INVALID_PASSWORD") {
          return "Current password is incorrect.";
        }
        if (normalized === "EMAIL_NOT_FOUND" || normalized === "USER_NOT_FOUND") {
          return "This account could not be verified.";
        }
        if (normalized.startsWith("WEAK_PASSWORD")) {
          return "New password must be at least 6 characters.";
        }
        if (normalized === "USER_DISABLED") {
          return "This account is disabled.";
        }
        if (normalized === "TOO_MANY_ATTEMPTS_TRY_LATER") {
          return "Too many attempts. Try again later.";
        }
        if (normalized === "OPERATION_NOT_ALLOWED") {
          return "Password authentication is not enabled for this account.";
        }
        return fallbackMessage;
      }

      function buildFirebaseRestUrl(pathname) {
        return "https://identitytoolkit.googleapis.com/v1/" + pathname + "?key=" + encodeURIComponent(FIREBASE_WEB_API_KEY);
      }

      function getFirebaseSessionCookieDomain() {
        if (typeof window === "undefined") {
          return "";
        }
        const hostname = String(window.location.hostname || "").trim();
        if (!hostname || hostname === "localhost" || hostname === "127.0.0.1") {
          return "";
        }
        const parts = hostname.split(".").filter(Boolean);
        if (parts.length < 2) {
          return "";
        }
        return "." + parts.slice(-2).join(".");
      }

      function writeFirebaseSessionCookie(token) {
        if (typeof document === "undefined") {
          return;
        }
        const normalizedToken = typeof token === "string" ? token.trim() : "";
        const secure = typeof window !== "undefined" ? window.location.protocol === "https:" : true;
        const maxAge = 7 * 24 * 60 * 60;
        const baseCookie = "__session=" + encodeURIComponent(normalizedToken)
          + "; Path=/; Max-Age=" + maxAge
          + "; SameSite=Lax"
          + (secure ? "; Secure" : "");
        const domain = getFirebaseSessionCookieDomain();
        document.cookie = baseCookie + (domain ? "; Domain=" + domain : "");
      }

      function clearFirebaseSessionCookie() {
        if (typeof document === "undefined") {
          return;
        }
        const secure = typeof window !== "undefined" ? window.location.protocol === "https:" : true;
        const expiredCookie = "__session=; Path=/; Expires=Thu, 01 Jan 1970 00:00:00 GMT; SameSite=Lax"
          + (secure ? "; Secure" : "");
        const domain = getFirebaseSessionCookieDomain();
        document.cookie = expiredCookie;
        if (domain) {
          document.cookie = expiredCookie + "; Domain=" + domain;
        }
      }

      function getPlaygroundFirebaseAuth() {
        if (!FIREBASE_WEB_API_KEY || !FIREBASE_AUTH_DOMAIN || !FIREBASE_PROJECT_ID) {
          return null;
        }
        if (playgroundFirebaseAuthInstance) {
          return playgroundFirebaseAuthInstance;
        }

        const firebaseConfig = {
          apiKey: FIREBASE_WEB_API_KEY,
          authDomain: FIREBASE_AUTH_DOMAIN,
          projectId: FIREBASE_PROJECT_ID,
          storageBucket: FIREBASE_STORAGE_BUCKET,
          messagingSenderId: FIREBASE_MESSAGING_SENDER_ID,
          appId: FIREBASE_APP_ID,
        };
        try {
          const existingApp = getApps().find((app) => app.name === PLAYGROUND_FIREBASE_APP_NAME);
          const firebaseApp = existingApp || initializeApp(firebaseConfig, PLAYGROUND_FIREBASE_APP_NAME);
          playgroundFirebaseAuthInstance = getAuth(firebaseApp);
          return playgroundFirebaseAuthInstance;
        } catch {
          return null;
        }
      }

      async function ensurePlaygroundFirebaseAuth() {
        const auth = getPlaygroundFirebaseAuth();
        if (!auth) {
          return null;
        }
        if (!playgroundFirebaseAuthReadyPromise) {
          playgroundFirebaseAuthReadyPromise = setPersistence(auth, browserLocalPersistence).catch(() => {});
        }
        await playgroundFirebaseAuthReadyPromise;
        return auth;
      }

      function createFetchAbortReason(name, message) {
        if (typeof DOMException === "function") {
          return new DOMException(message, name);
        }
        const error = new Error(message);
        error.name = name;
        return error;
      }

      function getSignalAbortReason(signal, fallbackMessage) {
        return signal && "reason" in signal && signal.reason
          ? signal.reason
          : createFetchAbortReason("AbortError", fallbackMessage);
      }

      function isFetchAbortError(error) {
        const name = String(error?.name || "").toLowerCase();
        const message = String(error?.message || error || "").toLowerCase();
        return name === "aborterror"
          || name === "timeouterror"
          || message.includes("aborted")
          || message.includes("signal is aborted")
          || message.includes("aborterror")
          || message.includes("timeouterror");
      }

      async function fetchJsonWithTimeout(input, init = {}, timeoutMs = 8000) {
        const controller = new AbortController();
        const externalSignal = init?.signal;
        const abortFromExternalSignal = () => {
          if (!controller.signal.aborted) {
            controller.abort(getSignalAbortReason(externalSignal, "Request was cancelled."));
          }
        };
        if (externalSignal) {
          if (externalSignal.aborted) {
            controller.abort(getSignalAbortReason(externalSignal, "Request was cancelled."));
          } else {
            externalSignal.addEventListener("abort", abortFromExternalSignal, { once: true });
          }
        }
        const normalizedTimeoutMs = Math.max(250, Number(timeoutMs) || 0);
        const timeoutId = window.setTimeout(() => {
          if (!controller.signal.aborted) {
            controller.abort(createFetchAbortReason("TimeoutError", "Request timed out after " + String(normalizedTimeoutMs) + "ms."));
          }
        }, normalizedTimeoutMs);

        try {
          const response = await fetch(input, {
            ...init,
            signal: controller.signal,
          });
          const data = await response.json().catch(() => ({}));
          return { response, data };
        } finally {
          window.clearTimeout(timeoutId);
          if (externalSignal) {
            externalSignal.removeEventListener("abort", abortFromExternalSignal);
          }
        }
      }

      function normalizeSessionIdentityValue(value) {
        return String(value || "").replace(/\\s+/g, " ").trim();
      }

      function getSessionIdentityObject(value) {
        return value && typeof value === "object" && !Array.isArray(value) ? value : null;
      }

      function pickFirstSessionIdentityValue(...values) {
        for (const value of values) {
          const normalizedValue = normalizeSessionIdentityValue(value);
          if (normalizedValue) {
            return normalizedValue;
          }
        }
        return "";
      }

      function normalizeSessionPhotoUrl(value) {
        const normalizedValue = normalizeSessionIdentityValue(value);
        if (!normalizedValue) {
          return "";
        }
        if (normalizedValue.startsWith("//")) {
          return "https:" + normalizedValue;
        }
        return normalizedValue;
      }

      function getPreferredSessionProviderProfile(...sources) {
        const providerEntries = [];
        sources.forEach((source) => {
          const providerUserInfo = Array.isArray(source?.providerUserInfo) ? source.providerUserInfo : [];
          providerUserInfo.forEach((entry) => {
            const normalizedEntry = getSessionIdentityObject(entry);
            if (normalizedEntry) {
              providerEntries.push(normalizedEntry);
            }
          });
        });

        if (!providerEntries.length) {
          return null;
        }

        return (
          providerEntries.find((entry) => normalizeSessionIdentityValue(entry.providerId).toLowerCase() === "google.com")
          || providerEntries.find((entry) => (
            pickFirstSessionIdentityValue(
              entry.displayName,
              entry.name,
              entry.email,
              entry.photoUrl,
              entry.photoURL,
              entry.avatarUrl,
              entry.picture
            )
          ))
          || null
        );
      }

      function extractSessionIdentityFromPayload(payload) {
        const root = getSessionIdentityObject(payload);
        const profile = getSessionIdentityObject(root?.profile);
        const user = getSessionIdentityObject(root?.user);
        const authProfile = getSessionIdentityObject(root?.authProfile);
        const preferredProvider = getPreferredSessionProviderProfile(root, profile, user, authProfile);

        const email = pickFirstSessionIdentityValue(
          root?.email,
          profile?.email,
          user?.email,
          authProfile?.email,
          preferredProvider?.email
        );
        const displayName = getTrustedDisplayName(
          pickFirstSessionIdentityValue(
            profile?.displayName,
            profile?.display_name,
            profile?.name,
            root?.displayName,
            root?.display_name,
            root?.name,
            user?.displayName,
            user?.display_name,
            user?.name,
            authProfile?.displayName,
            authProfile?.display_name,
            authProfile?.name,
            preferredProvider?.displayName,
            preferredProvider?.name
          ),
          email
        ) || formatEmailPrefixDisplayName(email);
        const photoURL = normalizeSessionPhotoUrl(
          pickFirstSessionIdentityValue(
            profile?.photoURL,
            profile?.photoUrl,
            profile?.photo_url,
            profile?.avatarUrl,
            profile?.avatarURL,
            profile?.avatar,
            profile?.picture,
            root?.photoURL,
            root?.photoUrl,
            root?.photo_url,
            root?.avatarUrl,
            root?.avatar,
            root?.picture,
            user?.photoURL,
            user?.photoUrl,
            user?.photo_url,
            user?.avatarUrl,
            user?.avatar,
            user?.picture,
            authProfile?.photoURL,
            authProfile?.photoUrl,
            authProfile?.photo_url,
            authProfile?.avatarUrl,
            authProfile?.avatar,
            authProfile?.picture,
            preferredProvider?.photoURL,
            preferredProvider?.photoUrl,
            preferredProvider?.photo_url,
            preferredProvider?.avatarUrl,
            preferredProvider?.avatar,
            preferredProvider?.picture
          )
        );
        const emailVerified = typeof root?.emailVerified === "boolean"
          ? root.emailVerified
          : (typeof authProfile?.emailVerified === "boolean" ? authProfile.emailVerified : undefined);

        return {
          email,
          displayName,
          photoURL: canRenderAvatarImage(photoURL) ? photoURL : "",
          emailVerified,
        };
      }

      function readNamedCookie(name) {
        if (typeof document === "undefined") {
          return "";
        }
        const normalizedName = String(name || "").trim();
        if (!normalizedName) {
          return "";
        }
        const escapedName = normalizedName.replace(/[.*+?^{}$()|[\\]\\\\]/g, "\\\\$&");
        const match = document.cookie.match(new RegExp("(?:^|; )" + escapedName + "=([^;]*)"));
        if (!match || typeof match[1] !== "string") {
          return "";
        }
        try {
          return decodeURIComponent(match[1]);
        } catch {
          return match[1];
        }
      }

      async function lookupFirebaseSessionIdentity() {
        const sessionToken = readNamedCookie("__session");
        if (!sessionToken) {
          return null;
        }

        const { response, data } = await fetchJsonWithTimeout(buildFirebaseRestUrl("accounts:lookup"), {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            idToken: sessionToken,
          }),
        }, 3000);
        if (!response.ok) {
          return null;
        }

        const user = Array.isArray(data?.users) ? getSessionIdentityObject(data.users[0]) : null;
        if (!user) {
          return null;
        }

        const identity = extractSessionIdentityFromPayload({
          email: user.email,
          emailVerified: user.emailVerified,
          user: {
            email: user.email,
            uid: user.localId || user.userId || user.id || "",
            displayName: user.displayName,
            name: user.displayName,
            photoURL: user.photoURL || user.photoUrl,
            photoUrl: user.photoUrl || user.photoURL,
            providerUserInfo: Array.isArray(user.providerUserInfo) ? user.providerUserInfo : [],
          },
        });
        return {
          ...identity,
          userId: pickFirstSessionIdentityValue(user.localId, user.userId, user.id),
        };
      }

      async function syncFirebaseSessionCookieFromCurrentUser(forceRefresh = false) {
        try {
          const auth = await ensurePlaygroundFirebaseAuth();
          const currentUser = auth?.currentUser || null;
          if (!currentUser) {
            return false;
          }
          const idToken = await currentUser.getIdToken(Boolean(forceRefresh));
          if (!idToken) {
            return false;
          }
          writeFirebaseSessionCookie(idToken);
          return true;
        } catch {
          return false;
        }
      }

