            const cleanLine = line.replace(/^(\\s*)(?:-\\s+|\\d+\\.\\s+)/, "$1");
            return cleanLine.replace(/^(\\s*)/, (_match, indent) => (
              String(indent || "") + (isOrderedList ? String(orderedIndex++) + ". " : "- ")
            ));
