        function getTeamPageApiErrorMessage(data, fallback = "Failed to load teams.") {
          const rawMessage = String(data?.message || data?.error || fallback || "").trim();
          const normalizedMessage = rawMessage.toLowerCase();
          const isHtmlRouteError = normalizedMessage.includes("<!doctype html")
            || normalizedMessage.includes("<html")
            || ["get", "post", "patch", "put", "delete"].some((method) =>
              normalizedMessage.includes("cannot " + method + " /teams")
            );
          if (isHtmlRouteError) {
            return "Team workspace API is not available on this backend yet. Redeploy the backend, then refresh this page.";
          }
          if (
            normalizedMessage.includes("signal is aborted")
            || normalizedMessage.includes("aborted without reason")
            || normalizedMessage.includes("aborterror")
          ) {
            return "The team data request was interrupted. Refresh the team page to try again.";
          }
          if (normalizedMessage.includes("timeouterror") || normalizedMessage.includes("request timed out")) {
            return "Team data is taking longer than expected to load. Refresh the team page to try again.";
          }
          return rawMessage || fallback;
        }

        function normalizeTeamPageTeamRecord(team) {
          const source = team && typeof team === "object" && !Array.isArray(team) ? team : {};
          return {
            ...source,
            permissionSet: normalizePlaygroundPermissionSet(source.permissionSet, "team"),
            rolePermissionSets: normalizePlaygroundTeamRolePermissionSets(source.rolePermissionSets || source.rolePermissions || source.permissionSets),
          };
        }

        function getTeamPageIdentitySources(record) {
          const source = record && typeof record === "object" && !Array.isArray(record) ? record : {};
          const metadata = source.metadata && typeof source.metadata === "object" && !Array.isArray(source.metadata) ? source.metadata : {};
          const sources = [
            source,
            source.user,
            source.profile,
            source.authProfile,
            source.account,
            source.member,
            source.identity,
            source.userProfile,
            source.accountProfile,
            source.publicProfile,
            source.firebaseUser,
            source.authUser,
            metadata,
            metadata.user,
            metadata.profile,
            metadata.authProfile,
            metadata.account,
            metadata.member,
            metadata.identity,
            metadata.userProfile,
            metadata.accountProfile,
            metadata.publicProfile,
            metadata.firebaseUser,
            metadata.authUser,
          ].filter((value) => value && typeof value === "object" && !Array.isArray(value));
          sources.slice().forEach((value) => {
            [value.providerUserInfo, value.providerData].forEach((providerProfiles) => {
              if (!Array.isArray(providerProfiles)) {
                return;
              }
              providerProfiles.forEach((providerProfile) => {
                if (providerProfile && typeof providerProfile === "object" && !Array.isArray(providerProfile)) {
                  sources.push(providerProfile);
                }
              });
            });
          });
          return sources;
        }

        function readTeamPageIdentityString(record, keys = []) {
          for (const source of getTeamPageIdentitySources(record)) {
            for (const key of keys) {
              const value = String(source?.[key] || "").replace(/\\s+/g, " ").trim();
              if (value) {
                return value;
              }
            }
          }
          return "";
        }

        function readTeamPageIdentityDisplayName(record) {
          const directName = readTeamPageIdentityString(record, [
            "displayName",
            "display_name",
            "name",
            "fullName",
            "full_name",
            "accountDisplayName",
            "accountName",
            "memberDisplayName",
            "memberName",
            "firebaseDisplayName",
            "providerDisplayName",
            "publicName",
            "username",
            "userName",
          ]);
          if (directName) {
            return directName;
          }
          for (const source of getTeamPageIdentitySources(record)) {
            const firstName = String(source.firstName || source.first_name || source.givenName || source.given_name || "").trim();
            const lastName = String(source.lastName || source.last_name || source.familyName || source.family_name || "").trim();
            const fullName = [firstName, lastName].filter(Boolean).join(" ").trim();
            if (fullName) {
              return fullName;
            }
          }
          return "";
        }

        function readTeamPageIdentityEmail(record) {
          return readTeamPageIdentityString(record, [
            "email",
            "emailAddress",
            "email_address",
            "mail",
            "primaryEmail",
            "primary_email",
          ]).toLowerCase();
        }

        function readTeamPageIdentityAvatarUrl(record) {
          return readTeamPageIdentityString(record, [
            "photoURL",
            "photoUrl",
            "photo_url",
            "avatarUrl",
            "avatarURL",
            "avatar",
            "picture",
            "imageUrl",
            "profileImageUrl",
            "profile_image_url",
          ]);
        }

        function getTeamPageMemberProfileKeyCandidates(record) {
          const source = record && typeof record === "object" && !Array.isArray(record) ? record : {};
          const values = [
            source.userId,
            source.user_id,
            source.uid,
            source.id,
            source.localId,
            source.local_id,
            source.memberId,
            source.member_id,
          ];
          getTeamPageIdentitySources(source).forEach((identitySource) => {
            values.push(
              identitySource.id,
              identitySource.uid,
              identitySource.userId,
              identitySource.user_id,
              identitySource.localId,
              identitySource.local_id,
              identitySource.memberId,
              identitySource.member_id,
              identitySource.email,
              identitySource.emailAddress,
              identitySource.email_address,
              identitySource.mail,
            );
          });
          return values.map((value) => String(value || "").trim()).filter(Boolean);
        }

        function buildTeamPageMemberProfileMap(payload) {
          const profileMap = new Map();
          const addProfile = (profile, explicitKey = "") => {
            if (!profile || typeof profile !== "object" || Array.isArray(profile)) {
              return;
            }
            const normalizedProfile = explicitKey
              ? { id: explicitKey, ...profile }
              : profile;
            const keys = getTeamPageMemberProfileKeyCandidates(normalizedProfile);
            keys.forEach((key) => profileMap.set(key.toLowerCase(), normalizedProfile));
          };
          const addProfiles = (value) => {
            if (Array.isArray(value)) {
              value.forEach((profile) => addProfile(profile));
              return;
            }
            if (!value || typeof value !== "object") {
              return;
            }
            if (
              readTeamPageIdentityDisplayName(value)
              || readTeamPageIdentityEmail(value)
              || getTeamPageMemberProfileKeyCandidates(value).length > 0
            ) {
              addProfile(value);
            }
            if (Array.isArray(value.data)) {
              value.data.forEach((profile) => addProfile(profile));
              return;
            }
            Object.entries(value).forEach(([key, profile]) => addProfile(profile, key));
          };
          [
            payload,
            payload?.profile,
            payload?.user,
            payload?.account,
            payload?.member,
            payload?.profiles,
            payload?.memberProfiles,
            payload?.member_profiles,
            payload?.users,
            payload?.accounts,
            payload?.items,
            payload?.results,
            payload?.data,
            payload?.data?.profile,
            payload?.data?.user,
            payload?.data?.account,
            payload?.data?.member,
            payload?.included?.profiles,
            payload?.included?.users,
            payload?.included?.accounts,
            payload?.data?.profiles,
            payload?.data?.memberProfiles,
            payload?.data?.users,
            payload?.data?.accounts,
            payload?.data?.items,
            payload?.data?.results,
          ].forEach(addProfiles);
          return profileMap;
        }

        function mergeTeamPageMemberProfiles(members, ...profilePayloads) {
          const profileMap = new Map();
          profilePayloads.forEach((payload) => {
            buildTeamPageMemberProfileMap(payload).forEach((profile, key) => {
              profileMap.set(key, profile);
            });
          });
          return (Array.isArray(members) ? members : []).map((member) => {
            const matchingProfile = getTeamPageMemberProfileKeyCandidates(member)
              .map((key) => profileMap.get(key.toLowerCase()))
              .find(Boolean);
            if (!matchingProfile) {
              return member;
            }
            const memberEmail = readTeamPageIdentityEmail(member);
            const profileEmail = readTeamPageIdentityEmail(matchingProfile);
            const email = memberEmail || profileEmail;
            const memberDisplayName = readTeamPageIdentityDisplayName(member);
            const profileDisplayName = readTeamPageIdentityDisplayName(matchingProfile);
            const displayName = getTrustedDisplayName(profileDisplayName, email)
              || getTrustedDisplayName(memberDisplayName, email);
            const avatarUrl = readTeamPageIdentityAvatarUrl(matchingProfile)
              || readTeamPageIdentityAvatarUrl(member);
            return {
              ...member,
              ...(displayName ? { displayName, name: displayName } : {}),
              ...(email ? { email } : {}),
              ...(avatarUrl ? { photoURL: avatarUrl, photoUrl: avatarUrl } : {}),
              profile: {
                ...(member.profile && typeof member.profile === "object" && !Array.isArray(member.profile) ? member.profile : {}),
                ...(matchingProfile && typeof matchingProfile === "object" ? matchingProfile : {}),
                ...(displayName ? { displayName, name: displayName } : {}),
                ...(email ? { email } : {}),
                ...(avatarUrl ? { photoURL: avatarUrl, photoUrl: avatarUrl } : {}),
              },
              user: {
                ...(member.user && typeof member.user === "object" && !Array.isArray(member.user) ? member.user : {}),
                ...(matchingProfile && typeof matchingProfile === "object" ? matchingProfile : {}),
                ...(displayName ? { displayName, name: displayName } : {}),
                ...(email ? { email } : {}),
                ...(avatarUrl ? { photoURL: avatarUrl, photoUrl: avatarUrl } : {}),
              },
            };
          });
        }

        async function fetchTeamPageMemberProfilePayload(teamId, members = [], options = {}) {
          const normalizedTeamId = String(teamId || "").trim();
          if (!normalizedTeamId) {
            return null;
          }
          const memberPayload = Array.isArray(members) ? members : [];
          const requestSignal = options && typeof options === "object" ? options.signal : undefined;
          try {
            const { response, data } = await fetchJsonWithTimeout(proxyBackendBase + "/team-member-profiles/lookup", {
              method: "POST",
              credentials: "include",
              cache: "no-store",
              signal: requestSignal,
              headers: {
                ...requestHeaders,
                "Content-Type": "application/json",
              },
              body: JSON.stringify({
                teamId: normalizedTeamId,
                members: memberPayload,
              }),
            }, 8000);
            if (response.ok) {
              const profiles = Array.isArray(data?.profiles)
                ? data.profiles
                : Array.isArray(data?.data)
                  ? data.data
                  : [];
              if (profiles.length > 0) {
                return data;
              }
            }
          } catch {}
          const profilePaths = [
            "/teams/" + encodeURIComponent(normalizedTeamId) + "/member-profiles",
            "/teams/" + encodeURIComponent(normalizedTeamId) + "/members/profiles",
          ];
          for (const path of profilePaths) {
            try {
              const { response, data } = await fetchJsonWithTimeout(proxyBackendBase + path, {
                method: "GET",
                credentials: "include",
                cache: "no-store",
                signal: requestSignal,
                headers: requestHeaders,
              }, 5000);
              if (response.ok) {
                return data;
              }
            } catch {}
          }
          return null;
        }

        function getOrganizationPageApiErrorMessage(data, fallback = "Failed to load organizations.") {
          const rawMessage = String(data?.message || data?.error || fallback || "").trim();
          const normalizedMessage = rawMessage.toLowerCase();
          if (
            normalizedMessage.includes("<!doctype html")
            || normalizedMessage.includes("<html")
            || ["get", "post", "patch", "put", "delete"].some((method) =>
              normalizedMessage.includes("cannot " + method + " /organizations")
            )
          ) {
            return "Organization API is not available on this backend yet. Redeploy the backend, then refresh this page.";
          }
          if (
            normalizedMessage.includes("signal is aborted")
            || normalizedMessage.includes("aborted without reason")
            || normalizedMessage.includes("aborterror")
          ) {
            return "The organization data request was interrupted. Refresh the organization page to try again.";
          }
          if (normalizedMessage.includes("timeouterror") || normalizedMessage.includes("request timed out")) {
            return "Organization data is taking longer than expected to load. Refresh the organization page to try again.";
          }
          return rawMessage || fallback;
        }

        function normalizeOrganizationPageRecord(organization) {
          const source = organization && typeof organization === "object" && !Array.isArray(organization) ? organization : {};
          const membership = source.membership && typeof source.membership === "object" && !Array.isArray(source.membership)
            ? source.membership
            : {};
          const metadata = source.metadata && typeof source.metadata === "object" && !Array.isArray(source.metadata)
            ? source.metadata
            : {};
          return {
            ...source,
            id: String(source.id || source.organizationId || source.organization_id || "").trim(),
            name: String(source.name || source.title || source.slug || "Organization").trim(),
            type: String(source.type || "company").trim().toLowerCase() || "company",
            role: (() => {
              const role = String(source.role || source.currentUserRole || source.viewerRole || membership.role || "member").trim().toLowerCase();
              return ["owner", "admin", "billing", "developer", "member", "viewer"].includes(role) ? role : "member";
            })(),
            membership,
            metadata,
            rolePermissionSets: normalizePlaygroundOrganizationRolePermissionSets(
              source.rolePermissionSets
              || source.rolePermissions
              || metadata.organizationRolePermissionSets
              || metadata.rolePermissionSets
            ),
          };
        }

        function getOrganizationPagePersonalOrganization(organizations) {
          const list = Array.isArray(organizations) ? organizations : [];
          return list.find((organization) => String(organization?.type || "").toLowerCase() === "personal")
            || list.find((organization) => String(organization?.ownerUserId || "") === String(sessionState.userId || ""))
            || list[0]
            || null;
        }

        function getOrganizationPageDisplayName(organization) {
          const normalizedOrganization = normalizeOrganizationPageRecord(organization);
          const name = normalizedOrganization.name || "Organization";
          if (normalizedOrganization.type === "personal" && name.trim().toLowerCase() === "personal") {
            return "Personal Organization";
          }
          return name;
        }

        function isOrganizationPageActiveOrganization(organization) {
          const organizationId = String(organization?.id || "").trim();
          if (!organizationId) {
            return false;
          }
          const explicitActiveOrganizationId = String(activeOrganizationId || "").trim();
          if (explicitActiveOrganizationId) {
            return organizationId === explicitActiveOrganizationId;
          }
          return organizationId === String(getOrganizationPagePersonalOrganization(organizationPageOrganizations)?.id || "").trim();
        }

        function setActiveOrganizationFromRecord(organization) {
          const normalizedOrganization = normalizeOrganizationPageRecord(organization);
          if (!normalizedOrganization.id) {
            return;
          }
          setActiveOrganizationId(normalizedOrganization.type === "personal" ? "" : normalizedOrganization.id);
        }

        function getComposerOrganizationOptions() {
          const organizations = Array.isArray(organizationPageOrganizations) ? organizationPageOrganizations : [];
          if (!organizations.length) {
            return [{ id: "__personal_workspace__", name: "Personal Workspace", description: "Workspace", isDefault: true }];
          }
          return organizations
            .map((organization) => {
              const normalizedOrganization = normalizeOrganizationPageRecord(organization);
              if (!normalizedOrganization.id) {
                return null;
              }
              return {
                id: normalizedOrganization.id,
                name: getOrganizationPageDisplayName(normalizedOrganization),
                description: normalizedOrganization.type === "personal" ? "Personal Organization" : "Company",
                isDefault: isOrganizationPageActiveOrganization(normalizedOrganization),
              };
            })
            .filter(Boolean);
        }

        function getActiveComposerOrganizationId() {
          const organizations = Array.isArray(organizationPageOrganizations) ? organizationPageOrganizations : [];
          const activeOrganization = organizations.find((organization) => isOrganizationPageActiveOrganization(organization))
            || getOrganizationPagePersonalOrganization(organizations);
          return String(activeOrganization?.id || "__personal_workspace__").trim();
        }

        function readOrganizationPageAvatarUrl(organization) {
          const source = organization && typeof organization === "object" && !Array.isArray(organization) ? organization : {};
          const directAvatarUrl = String(
            source.avatarUrl
            || source.avatarURL
            || source.photoUrl
            || source.photoURL
            || source.logoUrl
            || source.logoURL
            || source.imageUrl
            || source.imageURL
            || source.picture
            || ""
          ).trim();
          if (directAvatarUrl) {
            return directAvatarUrl;
          }
          const nestedProfile = source.profile && typeof source.profile === "object" && !Array.isArray(source.profile)
            ? source.profile
            : {};
          const nestedBrand = source.brand && typeof source.brand === "object" && !Array.isArray(source.brand)
            ? source.brand
            : {};
          return String(
            nestedProfile.avatarUrl
            || nestedProfile.photoUrl
            || nestedBrand.logoUrl
            || nestedBrand.avatarUrl
            || ""
          ).trim();
        }

        function getActiveSidebarOrganizationDisplay() {
          const organizations = Array.isArray(organizationPageOrganizations) ? organizationPageOrganizations : [];
          const activeOrganization = organizations.find((organization) => isOrganizationPageActiveOrganization(organization))
            || getOrganizationPagePersonalOrganization(organizations);
          const normalizedOrganization = activeOrganization ? normalizeOrganizationPageRecord(activeOrganization) : null;
          const name = hasShellAccess
            ? (normalizedOrganization ? getOrganizationPageDisplayName(normalizedOrganization) : "Personal Organization")
            : "Sign in";
          const avatarUrl = normalizeSessionPhotoUrl(
            readOrganizationPageAvatarUrl(activeOrganization)
            || accountAvatarUrl
          );
          return {
            name,
            initials: getAccountInitials(name),
            avatarUrl: canRenderAvatarImage(avatarUrl) ? avatarUrl : "",
          };
        }

        function handleComposerOrganizationChange(organizationId) {
          const normalizedOrganizationId = String(organizationId || "").trim();
          const organization = (Array.isArray(organizationPageOrganizations) ? organizationPageOrganizations : [])
            .find((entry) => String(entry?.id || "").trim() === normalizedOrganizationId);
          if (!organization) {
            return;
          }
          setActiveOrganizationFromRecord(organization);
        }

        async function loadOrganizationPageData(options = {}) {
          if (!hasRealAccess) {
            if (organizationPageLoadAbortControllerRef.current) {
              organizationPageLoadAbortControllerRef.current.abort(createFetchAbortReason("AbortError", "Organization page access changed."));
              organizationPageLoadAbortControllerRef.current = null;
            }
            setOrganizationPageOrganizations([]);
            setOrganizationPageMembers([]);
            setOrganizationPageInvitations([]);
            setOrganizationPageResources([]);
            setOrganizationPageBillingSummary(null);
            setOrganizationPageBillingError("");
            return;
          }
          if (organizationPageLoadAbortControllerRef.current) {
            organizationPageLoadAbortControllerRef.current.abort(createFetchAbortReason("AbortError", "A newer organization page load started."));
          }
          const loadAbortController = new AbortController();
          organizationPageLoadAbortControllerRef.current = loadAbortController;
          const loadSequenceId = organizationPageLoadSequenceRef.current + 1;
          organizationPageLoadSequenceRef.current = loadSequenceId;
          const isCurrentLoad = () => (
            organizationPageLoadSequenceRef.current === loadSequenceId
            && organizationPageLoadAbortControllerRef.current === loadAbortController
          );
          const hasSelectedOrganizationIdOverride = options
            && typeof options === "object"
            && Object.prototype.hasOwnProperty.call(options, "selectedOrganizationId");
          const requestedOrganizationId = String(hasSelectedOrganizationIdOverride ? options.selectedOrganizationId : organizationPageSelectedOrganizationId || "").trim();
          const isSilent = options?.silent === true;
          const listOnly = options?.listOnly === true;
          if (!isSilent) {
            setOrganizationPageLoading(true);
          }
          setOrganizationPageError("");
          try {
            const { response, data } = await fetchJsonWithTimeout(proxyBackendBase + "/organizations", {
              method: "GET",
              credentials: "include",
              cache: "no-store",
              signal: loadAbortController.signal,
              headers: baseAuthRequestHeaders,
            }, 12000);
            if (!isCurrentLoad()) {
              return;
            }
            if (!response.ok) {
              throw new Error(getOrganizationPageApiErrorMessage(data));
            }
            const organizations = (Array.isArray(data?.data) ? data.data : Array.isArray(data?.organizations) ? data.organizations : [])
              .map((organization) => normalizeOrganizationPageRecord(organization))
              .filter((organization) => organization.id);
            setOrganizationPageOrganizations(organizations);
            if (activeOrganizationId && !organizations.some((organization) => organization.id === activeOrganizationId)) {
              setActiveOrganizationId("");
            }
            const selectedOrganization = requestedOrganizationId
              ? organizations.find((organization) => organization.id === requestedOrganizationId) || null
              : null;
            const selectedOrganizationId = selectedOrganization?.id || "";
            setOrganizationPageSelectedOrganizationId(selectedOrganizationId);
            if (!selectedOrganizationId || listOnly) {
              setOrganizationPageMembers([]);
              setOrganizationPageInvitations([]);
              setOrganizationPageResources([]);
              setOrganizationPageBillingSummary(null);
              setOrganizationPageBillingError("");
              return;
            }
            const selectedOrganizationHeaders = {
              ...baseAuthRequestHeaders,
              [PLAYGROUND_ORGANIZATION_HEADER]: selectedOrganizationId,
            };
            const [membersResult, invitationsResult, resourcesResult, billingSummaryResult] = await Promise.allSettled([
              fetchJsonWithTimeout(proxyBackendBase + "/organizations/" + encodeURIComponent(selectedOrganizationId) + "/members", {
                method: "GET",
                credentials: "include",
                cache: "no-store",
                signal: loadAbortController.signal,
                headers: baseAuthRequestHeaders,
              }, 12000),
              fetchJsonWithTimeout(proxyBackendBase + "/organizations/" + encodeURIComponent(selectedOrganizationId) + "/invitations", {
                method: "GET",
                credentials: "include",
                cache: "no-store",
                signal: loadAbortController.signal,
                headers: baseAuthRequestHeaders,
              }, 10000),
              fetchJsonWithTimeout(proxyBackendBase + "/organizations/" + encodeURIComponent(selectedOrganizationId) + "/resources", {
                method: "GET",
                credentials: "include",
                cache: "no-store",
                signal: loadAbortController.signal,
                headers: selectedOrganizationHeaders,
              }, 10000),
              fetchJsonWithTimeout(proxyBackendBase + "/billing/organization/summary?activityLimit=6", {
                method: "GET",
                credentials: "include",
                cache: "no-store",
                signal: loadAbortController.signal,
                headers: selectedOrganizationHeaders,
              }, 10000),
            ]);
            if (!isCurrentLoad()) {
              return;
            }
            if (membersResult.status === "rejected") {
              throw membersResult.reason;
            }
            if (!membersResult.value.response.ok) {
              throw new Error(getOrganizationPageApiErrorMessage(membersResult.value.data, "Failed to load organization members."));
            }
            setOrganizationPageMembers(Array.isArray(membersResult.value.data?.data) ? membersResult.value.data.data : []);
            setOrganizationPageInvitations(
              invitationsResult.status === "fulfilled"
              && invitationsResult.value.response.ok
              && Array.isArray(invitationsResult.value.data?.data)
                ? invitationsResult.value.data.data
                : []
            );
            setOrganizationPageResources(
              resourcesResult.status === "fulfilled"
              && resourcesResult.value.response.ok
              && Array.isArray(resourcesResult.value.data?.data)
                ? resourcesResult.value.data.data
                : []
            );
            if (billingSummaryResult.status === "fulfilled" && billingSummaryResult.value.response.ok) {
              setOrganizationPageBillingSummary(billingSummaryResult.value.data || null);
              setOrganizationPageBillingError("");
            } else {
              const billingData = billingSummaryResult.status === "fulfilled" ? billingSummaryResult.value.data : null;
              const billingStatus = billingSummaryResult.status === "fulfilled" ? billingSummaryResult.value.response.status : 0;
              const billingMessage = billingStatus === 404
                ? "Organization billing summary is not available on this backend yet. Redeploy the backend, then refresh this page."
                : billingSummaryResult.status === "rejected"
                ? (billingSummaryResult.reason instanceof Error ? billingSummaryResult.reason.message : "")
                : getOrganizationPageApiErrorMessage(billingData, "Billing summary is not available for this organization yet.");
              setOrganizationPageBillingSummary(null);
              setOrganizationPageBillingError(billingMessage || "Billing summary is not available for this organization yet.");
            }
          } catch (error) {
            if (!isCurrentLoad() || loadAbortController.signal.aborted) {
              return;
            }
            setOrganizationPageError(getOrganizationPageApiErrorMessage({
              message: error instanceof Error ? error.message : "",
            }, isFetchAbortError(error)
              ? "Organization data is taking longer than expected to load. Refresh the organization page to try again."
              : "Failed to load organizations."));
          } finally {
            if (isCurrentLoad()) {
              if (!isSilent) {
                setOrganizationPageLoading(false);
              }
              organizationPageLoadAbortControllerRef.current = null;
            }
          }
        }

        async function handleCreateOrganization() {
          const name = String(organizationPageCreateName || "").trim();
          if (!name) {
            return;
          }
          setOrganizationPageActionId("create-organization");
          setOrganizationPageError("");
          try {
            const { response, data } = await fetchJsonWithTimeout(proxyBackendBase + "/organizations", {
              method: "POST",
              credentials: "include",
              cache: "no-store",
              headers: {
                ...baseAuthRequestHeaders,
                "Content-Type": "application/json",
              },
              body: JSON.stringify({ name }),
            }, 10000);
            if (!response.ok) {
              throw new Error(data?.message || data?.error || "Failed to create organization.");
            }
            const organization = normalizeOrganizationPageRecord(data?.data || data?.organization || data);
            setOrganizationPageCreateName("");
            setOrganizationPageCreateModalOpen(false);
            if (organization.id) {
              setActiveOrganizationFromRecord(organization);
              setOrganizationPageSelectedOrganizationId(organization.id);
            }
            await loadOrganizationPageData({ selectedOrganizationId: organization.id || "" });
          } catch (error) {
            setOrganizationPageError(error instanceof Error ? error.message : "Failed to create organization.");
          } finally {
            setOrganizationPageActionId("");
          }
        }

