        function applyOrganizationRolePermissionSetLocally(organizationId, roleId, permissionSet) {
          const normalizedOrganizationId = String(organizationId || "").trim();
          const normalizedRoleId = normalizePlaygroundOrganizationRoleId(roleId, "");
          if (!normalizedOrganizationId || !normalizedRoleId || normalizedRoleId === "owner") {
            return;
          }
          const normalizedPermissionSet = normalizePlaygroundPermissionSet(permissionSet, "organization_role");
          setOrganizationPageOrganizations((current) => (Array.isArray(current) ? current : []).map((organization) => {
            const normalizedOrganization = normalizeOrganizationPageRecord(organization);
            if (normalizedOrganization.id !== normalizedOrganizationId) {
              return normalizedOrganization;
            }
            const rolePermissionSets = normalizePlaygroundOrganizationRolePermissionSets(normalizedOrganization.rolePermissionSets);
            const nextRolePermissionSets = {
              ...rolePermissionSets,
              [normalizedRoleId]: normalizedPermissionSet,
            };
            return normalizeOrganizationPageRecord({
              ...normalizedOrganization,
              rolePermissionSets: nextRolePermissionSets,
              metadata: {
                ...(normalizedOrganization.metadata || {}),
                organizationRolePermissionSets: nextRolePermissionSets,
              },
            });
          }));
        }

        async function persistOrganizationRolePermissionSet(organizationId, roleId, permissionSet) {
          const normalizedOrganizationId = String(organizationId || "").trim();
          const normalizedRoleId = normalizePlaygroundOrganizationRoleId(roleId, "");
          if (!normalizedOrganizationId || !normalizedRoleId || normalizedRoleId === "owner") {
            return null;
          }
          const selectedOrganization = organizationPageOrganizations.find((organization) => String(organization?.id || "") === normalizedOrganizationId) || null;
          const currentRolePermissionSets = normalizePlaygroundOrganizationRolePermissionSets(selectedOrganization?.rolePermissionSets);
          const nextRolePermissionSets = {
            ...currentRolePermissionSets,
            [normalizedRoleId]: normalizePlaygroundPermissionSet(permissionSet, "organization_role"),
          };
          const nextMetadata = {
            ...(selectedOrganization?.metadata || {}),
            organizationRolePermissionSets: nextRolePermissionSets,
          };
          const { response, data } = await fetchJsonWithTimeout(
            proxyBackendBase + "/organizations/" + encodeURIComponent(normalizedOrganizationId),
            {
              method: "PATCH",
              credentials: "include",
              cache: "no-store",
              headers: {
                ...baseAuthRequestHeaders,
                "Content-Type": "application/json",
                [PLAYGROUND_ORGANIZATION_HEADER]: normalizedOrganizationId,
              },
              body: JSON.stringify({ metadata: nextMetadata }),
            },
            10000
          );
          if (!response.ok) {
            throw new Error(data?.message || data?.error || "Failed to update organization role permissions.");
          }
          const updatedOrganization = normalizeOrganizationPageRecord(data?.data || data?.organization || data);
          if (updatedOrganization.id) {
            setOrganizationPageOrganizations((current) => (Array.isArray(current) ? current : []).map((organization) =>
              String(organization?.id || "") === updatedOrganization.id ? updatedOrganization : normalizeOrganizationPageRecord(organization)
            ));
          }
          return updatedOrganization;
        }

        function updateOrganizationRolePermissionSet(roleId, updater) {
          const normalizedRoleId = normalizePlaygroundOrganizationRoleId(roleId, "");
          const organizationId = String(organizationPageSelectedOrganizationId || "").trim();
          const selectedOrganization = organizationPageOrganizations.find((organization) => String(organization?.id || "") === organizationId) || null;
          if (!organizationId || !selectedOrganization || !normalizedRoleId || normalizedRoleId === "owner") {
            return;
          }
          const currentRolePermissionSets = normalizePlaygroundOrganizationRolePermissionSets(selectedOrganization.rolePermissionSets);
          const currentPermissionSet = normalizePlaygroundPermissionSet(currentRolePermissionSets[normalizedRoleId], "organization_role");
          const nextPermissionSet = normalizePlaygroundPermissionSet(
            typeof updater === "function" ? updater(currentPermissionSet) : updater,
            "organization_role"
          );
          applyOrganizationRolePermissionSetLocally(organizationId, normalizedRoleId, nextPermissionSet);
          const actionId = "organization-role-permissions:" + normalizedRoleId;
          setOrganizationPageActionId(actionId);
          setOrganizationPageError("");
          void persistOrganizationRolePermissionSet(organizationId, normalizedRoleId, nextPermissionSet)
            .catch((error) => {
              applyOrganizationRolePermissionSetLocally(organizationId, normalizedRoleId, currentPermissionSet);
              setOrganizationPageError(error instanceof Error ? error.message : "Failed to update organization role permissions.");
            })
            .finally(() => {
              setOrganizationPageActionId((current) => current === actionId ? "" : current);
            });
        }

        function updateOrganizationRolePermissionRingAccess(roleId, ringId, access) {
          updateOrganizationRolePermissionSet(roleId, (currentPermissionSet) => ({
            ...currentPermissionSet,
            rings: {
              ...(currentPermissionSet.rings || {}),
              [ringId]: {
                ...((currentPermissionSet.rings || {})[ringId] || {}),
                defaultAccess: normalizePlaygroundPermissionAccess(access),
              },
            },
          }));
        }

        function updateOrganizationRolePermissionActionRing(roleId, actionId, ringId) {
          const actionDefinition = getPlaygroundPermissionActionDefinition(actionId);
          if (!actionDefinition) return;
          updateOrganizationRolePermissionSet(roleId, (currentPermissionSet) => {
            const existingAction = (currentPermissionSet.actions || {})[actionId] || {};
            return {
              ...currentPermissionSet,
              actions: {
                ...(currentPermissionSet.actions || {}),
                [actionId]: buildPlaygroundPermissionActionPolicy(
                  currentPermissionSet,
                  actionDefinition,
                  existingAction,
                  getPlaygroundPermissionActionExplicitAccess(currentPermissionSet, actionDefinition),
                  ringId
                ),
              },
            };
          });
        }

        function updateOrganizationRolePermissionActionAccess(roleId, actionId, access) {
          const actionDefinition = getPlaygroundPermissionActionDefinition(actionId);
          if (!actionDefinition) return;
          updateOrganizationRolePermissionSet(roleId, (currentPermissionSet) => {
            const existingAction = (currentPermissionSet.actions || {})[actionId] || {};
            return {
              ...currentPermissionSet,
              actions: {
                ...(currentPermissionSet.actions || {}),
                [actionId]: buildPlaygroundPermissionActionPolicy(
                  currentPermissionSet,
                  actionDefinition,
                  existingAction,
                  normalizePlaygroundPermissionAccess(access, "")
                ),
              },
            };
          });
        }

        async function loadTeamPageData(options = {}) {
          if (!hasRealAccess) {
            if (teamPageLoadAbortControllerRef.current) {
              teamPageLoadAbortControllerRef.current.abort(createFetchAbortReason("AbortError", "Team page access changed."));
              teamPageLoadAbortControllerRef.current = null;
            }
            return;
          }
          if (teamPageLoadAbortControllerRef.current) {
            teamPageLoadAbortControllerRef.current.abort(createFetchAbortReason("AbortError", "A newer team page load started."));
          }
          const loadAbortController = new AbortController();
          teamPageLoadAbortControllerRef.current = loadAbortController;
          const loadSequenceId = teamPageLoadSequenceRef.current + 1;
          teamPageLoadSequenceRef.current = loadSequenceId;
          const isCurrentLoad = () => (
            teamPageLoadSequenceRef.current === loadSequenceId
            && teamPageLoadAbortControllerRef.current === loadAbortController
          );
          const hasSelectedTeamIdOverride = options
            && typeof options === "object"
            && Object.prototype.hasOwnProperty.call(options, "selectedTeamId");
          const requestedTeamId = String(hasSelectedTeamIdOverride ? options.selectedTeamId : teamPageSelectedTeamId || "").trim();
          setTeamPageLoading(true);
          setTeamPageError("");
          setTeamPageRequiresPlan(false);
          try {
            const { response, data } = await fetchJsonWithTimeout(proxyBackendBase + "/teams", {
              method: "GET",
              credentials: "include",
              cache: "no-store",
              signal: loadAbortController.signal,
              headers: requestHeaders,
            }, 12000);
            if (!isCurrentLoad()) {
              return;
            }
            if (!response.ok) {
              if (response.status === 402 || data?.requiredPlan === "team") {
                setTeamPageRequiresPlan(true);
                setTeamPageTeams([]);
                setTeamPageMembers([]);
                setTeamPageInvitations([]);
                setTeamPageShares([]);
                return;
              }
              throw new Error(getTeamPageApiErrorMessage(data));
            }
            const teams = (Array.isArray(data?.data) ? data.data : Array.isArray(data?.teams) ? data.teams : [])
              .map((team) => normalizeTeamPageTeamRecord(team));
            setTeamPageTeams(teams);
            const selectedTeam = requestedTeamId
              ? teams.find((team) => team.id === requestedTeamId) || null
              : null;
            const selectedTeamId = selectedTeam?.id || "";
            setTeamPageSelectedTeamId(selectedTeamId);
            if (selectedTeamId !== String(teamPageSelectedTeamId || "").trim()) {
              setTeamPageMembers([]);
              setTeamPageInvitations([]);
              setTeamPageShares([]);
            }
            if (!selectedTeamId) {
              setTeamPageMembers([]);
              setTeamPageInvitations([]);
              setTeamPageShares([]);
              return;
            }
            const [membersResult, invitationsResult, sharesResult] = await Promise.allSettled([
              fetchJsonWithTimeout(proxyBackendBase + "/teams/" + encodeURIComponent(selectedTeamId) + "/members?includeProfiles=1&includeUsers=1&include=profile,user,account&expand=profile,user,account", {
                method: "GET",
                credentials: "include",
                cache: "no-store",
                signal: loadAbortController.signal,
                headers: requestHeaders,
              }, 15000),
              fetchJsonWithTimeout(proxyBackendBase + "/teams/" + encodeURIComponent(selectedTeamId) + "/invitations", {
                method: "GET",
                credentials: "include",
                cache: "no-store",
                signal: loadAbortController.signal,
                headers: requestHeaders,
              }, 10000),
              fetchJsonWithTimeout(proxyBackendBase + "/teams/" + encodeURIComponent(selectedTeamId) + "/resource-shares", {
                method: "GET",
                credentials: "include",
                cache: "no-store",
                signal: loadAbortController.signal,
                headers: requestHeaders,
              }, 10000),
            ]);
            if (!isCurrentLoad()) {
              return;
            }
            if (membersResult.status === "rejected") {
              throw membersResult.reason;
            }
            if (!membersResult.value.response.ok) {
              throw new Error(getTeamPageApiErrorMessage(membersResult.value.data));
            }
            const rawMembers = Array.isArray(membersResult.value.data?.data) ? membersResult.value.data.data : [];
            const memberProfilesPayload = await fetchTeamPageMemberProfilePayload(selectedTeamId, rawMembers, { signal: loadAbortController.signal });
            if (!isCurrentLoad()) {
              return;
            }
            setTeamPageMembers(mergeTeamPageMemberProfiles(rawMembers, membersResult.value.data, memberProfilesPayload));
            setTeamPageInvitations(
              invitationsResult.status === "fulfilled"
              && invitationsResult.value.response.ok
              && Array.isArray(invitationsResult.value.data?.data)
                ? invitationsResult.value.data.data
                : []
            );
            setTeamPageShares(
              sharesResult.status === "fulfilled"
              && sharesResult.value.response.ok
              && Array.isArray(sharesResult.value.data?.data)
                ? sharesResult.value.data.data
                : []
            );
          } catch (error) {
            if (!isCurrentLoad() || loadAbortController.signal.aborted) {
              return;
            }
            setTeamPageError(getTeamPageApiErrorMessage({
              message: error instanceof Error ? error.message : "",
            }, isFetchAbortError(error)
              ? "Team data is taking longer than expected to load. Refresh the team page to try again."
              : "Failed to load teams."));
          } finally {
            if (isCurrentLoad()) {
              setTeamPageLoading(false);
              teamPageLoadAbortControllerRef.current = null;
            }
          }
        }

        async function handleCreateTeam() {
          const name = String(teamPageCreateName || "").trim();
          if (!name) {
            return;
          }
          const inviteEmails = String(teamPageCreateInviteEmails || "")
            .split(/[\\s,;]+/)
            .map((email) => email.trim())
            .filter(Boolean);
          setTeamPageActionId("create-team");
          setTeamPageError("");
          try {
            const { response, data } = await fetchJsonWithTimeout(proxyBackendBase + "/teams", {
              method: "POST",
              credentials: "include",
              cache: "no-store",
              headers: {
                ...requestHeaders,
                "Content-Type": "application/json",
              },
              body: JSON.stringify({ name }),
            }, 8000);
            if (!response.ok) {
              throw new Error(data?.message || data?.error || "Failed to create team.");
            }
            setTeamPageCreateName("");
            setTeamPageCreateInviteEmails("");
            setTeamPageCreateInviteRole("member");
            setTeamPageCreateModalOpen(false);
            const team = data?.data || data?.team || null;
            const teamId = String(team?.id || "").trim();
            let invitationErrorMessage = "";
            if (teamId && inviteEmails.length > 0) {
              const invitationResults = await Promise.allSettled(inviteEmails.map((email) =>
                fetchJsonWithTimeout(proxyBackendBase + "/teams/" + encodeURIComponent(teamId) + "/invitations", {
                  method: "POST",
                  credentials: "include",
                  cache: "no-store",
                  headers: {
                    ...requestHeaders,
                    "Content-Type": "application/json",
                  },
                  body: JSON.stringify({ email, role: getPlaygroundTeamRoleApiValue(teamPageCreateInviteRole) }),
                }, 8000)
              ));
              const failedInvitation = invitationResults.find((result) =>
                result.status === "rejected" || (result.value && !result.value.response?.ok)
              );
              if (failedInvitation) {
                invitationErrorMessage = "Team created, but one or more invitations could not be sent.";
              }
            }
            if (team?.id) {
              setTeamPageSelectedTeamId(team.id);
            }
            await loadTeamPageData({ selectedTeamId: team?.id || "" });
            if (invitationErrorMessage) {
              setTeamPageError(invitationErrorMessage);
            }
          } catch (error) {
            setTeamPageError(error instanceof Error ? error.message : "Failed to create team.");
          } finally {
            setTeamPageActionId("");
          }
        }

