          setWelcomeProjectPickerOpen(true);
          setWelcomeProjectPickerValue(selectedProjectId);
          setWelcomeProjectPickerError("");
          setWelcomeProjectPickerProjects([]);
          void loadWelcomeProjectPickerProjects();
