async function proxyAiosJsonRequest(req, res, upstreamPath, method) {
  try {
    const requestUrl = new URL(req.url || "/", `http://localhost:${port}`);
    const upstreamTarget = new URL(`${aiosOrigin}${upstreamPath}`);
    upstreamTarget.search = requestUrl.search;

    const headers = {
      cookie: req.headers.cookie || "",
      authorization: req.headers.authorization || "",
      "x-api-key": req.headers["x-api-key"] || "",
      "content-type": req.headers["content-type"] || "application/json",
    };

    const init = {
      method,
      headers,
    };

    if (method !== "GET" && method !== "HEAD") {
      const body = await readRequestBody(req);
      init.body = JSON.stringify(body);
    }

    const upstream = await fetch(upstreamTarget.toString(), init);
    const text = await upstream.text();
    let parsed = {};
    try {
      parsed = text ? JSON.parse(text) : {};
    } catch {
      parsed = { message: text };
    }

    const responseHeaders = {
      "Content-Type": "application/json; charset=utf-8",
      "Cache-Control": "no-store",
    };
    const setCookie = upstream.headers.get("set-cookie");
    if (setCookie) {
      responseHeaders["Set-Cookie"] = setCookie;
    }

    res.writeHead(upstream.status, responseHeaders);
    res.end(JSON.stringify(parsed));
  } catch (error) {
    return sendJson(res, 502, {
      error: "Failed to proxy aiOS JSON request",
      message: error instanceof Error ? error.message : String(error),
    });
  }
}

async function handleAiosUserSessionRequest(req, res) {
  const baseHeaders = {
    cookie: req.headers.cookie || "",
    authorization: req.headers.authorization || "",
    "x-api-key": req.headers["x-api-key"] || "",
    "content-type": req.headers["content-type"] || "application/json",
  };

  async function fetchAiosSessionJson(upstreamPath) {
    const upstreamTarget = new URL(`${aiosOrigin}${upstreamPath}`);
    const upstream = await fetch(upstreamTarget.toString(), {
      method: "GET",
      headers: baseHeaders,
    });
    const text = await upstream.text();
    let data = {};
    try {
      data = text ? JSON.parse(text) : {};
    } catch {
      data = { message: text };
    }
    return {
      ok: upstream.ok,
      status: upstream.status,
      data,
      setCookie: upstream.headers.get("set-cookie") || "",
    };
  }

  try {
    const [profileResult, streamingResult] = await Promise.all([
      fetchAiosSessionJson("/api/user/profile"),
      fetchAiosSessionJson("/api/user/streaming-key").catch((error) => ({
        ok: false,
        status: 502,
        data: {
          error: "Failed to load runner access.",
          message: error instanceof Error ? error.message : String(error),
        },
        setCookie: "",
      })),
    ]);

    const responseHeaders = {
      "Content-Type": "application/json; charset=utf-8",
      "Cache-Control": "no-store",
    };
    const setCookieHeaders = [profileResult.setCookie, streamingResult.setCookie].filter(Boolean);
    if (setCookieHeaders.length) {
      responseHeaders["Set-Cookie"] = setCookieHeaders;
    }

    if (!profileResult.ok) {
      res.writeHead(profileResult.status, responseHeaders);
      res.end(JSON.stringify(profileResult.data || {}));
      return;
    }

    res.writeHead(200, responseHeaders);
    res.end(JSON.stringify({
      profile: profileResult.data || {},
      streaming: streamingResult.data || {},
      streamingOk: Boolean(streamingResult.ok),
      streamingStatus: streamingResult.status,
    }));
  } catch (error) {
    return sendJson(res, 502, {
      error: "Failed to load account session.",
      message: error instanceof Error ? error.message : String(error),
    });
  }
}

function shouldRewriteNotionRedirectUri(value) {
  if (!value) {
    return false;
  }
  try {
    const parsed = new URL(value);
    return parsed.hostname === "localhost" || parsed.hostname === "127.0.0.1" || parsed.hostname === "::1";
  } catch {
    return false;
  }
}

function normalizeNotionAuthUrlForLocalDemo(authUrl) {
  if (!authUrl || !notionOauthCallbackUri) {
    return authUrl;
  }
  try {
    const parsed = new URL(authUrl);
    const currentRedirectUri = parsed.searchParams.get("redirect_uri") || "";
    if (shouldRewriteNotionRedirectUri(currentRedirectUri)) {
      parsed.searchParams.set("redirect_uri", notionOauthCallbackUri);
    }
    return parsed.toString();
  } catch {
    return authUrl;
  }
}

async function proxyAiosNotionLoginRequest(req, res) {
  try {
    const requestUrl = new URL(req.url || "/", `http://localhost:${port}`);
    const upstreamTarget = new URL(`${aiosOrigin}/api/notion/login`);
    upstreamTarget.search = requestUrl.search;

    const headers = {
      cookie: req.headers.cookie || "",
      authorization: req.headers.authorization || "",
      "x-api-key": req.headers["x-api-key"] || "",
      "content-type": req.headers["content-type"] || "application/json",
    };

    const body = await readRequestBody(req);
    const upstream = await fetch(upstreamTarget.toString(), {
      method: "POST",
      headers,
      body: JSON.stringify(body),
    });
    const text = await upstream.text();
    let parsed = {};
    try {
      parsed = text ? JSON.parse(text) : {};
    } catch {
      parsed = { message: text };
    }

    if (typeof parsed?.authUrl === "string") {
      const normalizedAuthUrl = normalizeNotionAuthUrlForLocalDemo(parsed.authUrl);
      if (normalizedAuthUrl !== parsed.authUrl) {
        console.info("[demo-server] Rewrote local Notion OAuth redirect_uri for demo login.", {
          callbackUri: notionOauthCallbackUri,
        });
      }
      parsed = {
        ...parsed,
        authUrl: normalizedAuthUrl,
      };
    }

    const responseHeaders = {
      "Content-Type": "application/json; charset=utf-8",
      "Cache-Control": "no-store",
    };
    const setCookie = upstream.headers.get("set-cookie");
    if (setCookie) {
      responseHeaders["Set-Cookie"] = setCookie;
    }

    res.writeHead(upstream.status, responseHeaders);
    res.end(JSON.stringify(parsed));
  } catch (error) {
    return sendJson(res, 502, {
      error: "Failed to proxy Notion login request",
      message: error instanceof Error ? error.message : String(error),
    });
  }
}

async function proxyAiosLatestBriefingHtml(req, res) {
  try {
    const briefingMetaResponse = await fetch(new URL("/api/briefing/url", aiosOrigin).toString(), {
      method: "GET",
    });
    const briefingMetaText = await briefingMetaResponse.text();
    let briefingMeta = {};
    try {
      briefingMeta = briefingMetaText ? JSON.parse(briefingMetaText) : {};
    } catch {
      briefingMeta = {};
    }

    if (!briefingMetaResponse.ok) {
      return sendJson(res, briefingMetaResponse.status, {
        error: "Failed to resolve briefing URL",
        message: briefingMeta?.message || briefingMeta?.error || "Failed to load the latest daily briefing.",
      });
    }

    const briefingPublicUrl = typeof briefingMeta?.url === "string" ? briefingMeta.url.trim() : "";
    if (!briefingPublicUrl) {
      return sendJson(res, 404, {
        error: "No briefing found",
        message: "No daily briefing is available yet.",
      });
    }

    const briefingHtmlResponse = await fetch(briefingPublicUrl, {
      method: "GET",
    });
    const briefingHtml = await briefingHtmlResponse.text();
    if (!briefingHtmlResponse.ok) {
      return sendJson(res, briefingHtmlResponse.status, {
        error: "Failed to load briefing HTML",
        message: briefingHtml || "Unable to load the daily briefing preview.",
      });
    }

    const escapedBaseHref = briefingPublicUrl
      .replace(/&/g, "&amp;")
      .replace(/"/g, "&quot;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;");
    const baseTag = `<base href="${escapedBaseHref}" />`;
    const shellStyles =
      '<style>html,body{margin:0;padding:0;background:#fff;color:#111;font-family:ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;}img,svg,video,canvas,iframe{max-width:100%;height:auto;}pre{white-space:pre-wrap;word-break:break-word;}table{max-width:100%;border-collapse:collapse;}*{box-sizing:border-box;}</style>';
    let rewrittenHtml = String(briefingHtml || "");
    if (/<head[\s>]/i.test(rewrittenHtml)) {
      rewrittenHtml = rewrittenHtml.replace(/<head(\s[^>]*)?>/i, (match) => `${match}${baseTag}${shellStyles}`);
    } else if (/<html[\s>]/i.test(rewrittenHtml)) {
      rewrittenHtml = rewrittenHtml.replace(/<html(\s[^>]*)?>/i, (match) => `${match}<head>${baseTag}${shellStyles}</head>`);
    } else {
      rewrittenHtml = `<!doctype html><html><head><meta charset="utf-8" />${baseTag}${shellStyles}</head><body>${rewrittenHtml}</body></html>`;
    }

    res.writeHead(200, {
      "Content-Type": "text/html; charset=utf-8",
      "Cache-Control": "no-store",
    });
    res.end(rewrittenHtml);
  } catch (error) {
    return sendJson(res, 502, {
      error: "Failed to proxy latest briefing HTML",
      message: error instanceof Error ? error.message : String(error),
    });
  }
}

async function proxyPlaygroundCustomSkills(req, res) {
  try {
    const normalizeSkillRecord = (skill) => {
      if (!skill || typeof skill !== "object") {
        return null;
      }
      const codeFiles = Array.isArray(skill.codeFiles)
        ? skill.codeFiles
        : Array.isArray(skill.files)
          ? skill.files
          : [];
      return {
        ...skill,
        codeFiles: codeFiles
          .filter((file) => file && typeof file === "object" && typeof file.name === "string" && file.name.trim())
          .map((file) => ({
            name: String(file.name || "").trim(),
            content: typeof file.content === "string" ? file.content : "",
            language: typeof file.language === "string" ? file.language : undefined,
          })),
        isCustom: true,
      };
    };
    const mergeSkillLists = (...lists) => {
      const merged = new Map();
      lists.flat().forEach((skill) => {
        const normalized = normalizeSkillRecord(skill);
        if (!normalized?.id) {
          return;
        }
        merged.set(normalized.id, normalized);
      });
      return Array.from(merged.values());
    };

    const requestUrl = new URL(req.url || "/", `http://localhost:${port}`);
    let projectId = requestUrl.searchParams.get("projectId")?.trim() || "";
    const cookie = req.headers.cookie || "";
    const authorization = req.headers.authorization || "";
    const apiKey = normalizePlaygroundApiKey(readHeader(req, "x-api-key"));
    let resolvedApiKey = apiKey;
    let aiosSkills = [];

    if (!projectId && (cookie || authorization)) {
      const profileResponse = await fetch(`${aiosOrigin}/api/user/profile`, {
        method: "GET",
        headers: {
          cookie,
          authorization,
        },
      });

      if (profileResponse.ok) {
        const profileData = await profileResponse.json().catch(() => ({}));
        projectId = typeof profileData?.profile?.projectId === "string"
          ? profileData.profile.projectId.trim()
          : "";
      }
    }

    const aiosProjectId = projectId || "__runner_playground__";
    if (projectId || apiKey || cookie || authorization) {
      const aiosTarget = new URL(`${aiosOrigin}/api/projects/${encodeURIComponent(aiosProjectId)}/skills`);
      const aiosResponse = await fetch(aiosTarget.toString(), {
        method: "GET",
        headers: withProxyOrganizationHeader(req, {}, {
          cookie,
          authorization,
          ...(apiKey ? { "x-api-key": apiKey } : {}),
        }),
      });
      const aiosText = await aiosResponse.text();
      let aiosParsed = {};
      try {
        aiosParsed = aiosText ? JSON.parse(aiosText) : {};
      } catch {
        aiosParsed = { message: aiosText };
      }

      if (aiosResponse.ok) {
        aiosSkills = Array.isArray(aiosParsed?.skills) ? aiosParsed.skills : [];
        if (aiosSkills.length > 0 && !apiKey) {
          return sendJson(res, 200, {
            skills: mergeSkillLists(aiosSkills),
            source: "aios",
          });
        }
      }

      if (!aiosResponse.ok && !isUnauthorizedHttpStatus(aiosResponse.status)) {
        return sendJson(res, aiosResponse.status, aiosParsed);
      }
    }

    if (!resolvedApiKey && (cookie || authorization)) {
      const streamingResponse = await fetch(`${aiosOrigin}/api/user/streaming-key`, {
        method: "GET",
        headers: {
          cookie,
          authorization,
        },
      });
      if (streamingResponse.ok) {
        const streamingData = await streamingResponse.json().catch(() => ({}));
        const nextApiKey = typeof streamingData?.apiKey === "string" ? streamingData.apiKey.trim() : "";
        if (nextApiKey) {
          resolvedApiKey = nextApiKey;
        }
      }
    }

    const upstreamHeader = readHeader(req, "x-runner-upstream-url");
    if (!resolvedApiKey) {
      return sendJson(res, 200, { skills: [], source: "none" });
    }

    const upstreamTarget = new URL(`${normalizeBackendUrl(upstreamHeader || defaultUpstreamOrigin)}/v1/skills`);
    const upstreamResponse = await fetch(upstreamTarget.toString(), {
      method: "GET",
      headers: withProxyOrganizationHeader(req, {}, {
        "X-API-Key": resolvedApiKey,
      }),
    });
    const upstreamText = await upstreamResponse.text();
    let upstreamParsed = {};
    try {
      upstreamParsed = upstreamText ? JSON.parse(upstreamText) : {};
    } catch {
      upstreamParsed = { message: upstreamText };
    }

    if (!upstreamResponse.ok) {
      if (aiosSkills.length > 0) {
        return sendJson(res, 200, {
          skills: mergeSkillLists(aiosSkills),
          source: "aios",
        });
      }
      return sendJson(res, upstreamResponse.status, upstreamParsed);
    }

    const backendSkills = Array.isArray(upstreamParsed?.data)
      ? upstreamParsed.data
      : Array.isArray(upstreamParsed?.skills)
        ? upstreamParsed.skills
        : [];

    return sendJson(res, 200, {
      skills: mergeSkillLists(aiosSkills, backendSkills),
      source: aiosSkills.length > 0 ? "merged" : "backend",
    });
  } catch (error) {
    return sendJson(res, 502, {
      error: "Failed to load playground custom skills",
      message: error instanceof Error ? error.message : String(error),
    });
  }
}

async function serveDistAsset(req, res) {
  const pathname = new URL(req.url, `http://localhost:${port}`).pathname;
  const localPath = path.join(packageRoot, pathname);
  const normalized = path.normalize(localPath);

  if (!normalized.startsWith(distRoot)) {
    res.writeHead(403);
    res.end("Forbidden");
    return;
  }

  try {
    const file = await fs.readFile(normalized);
    const contentType = pathname.endsWith(".js")
      ? "text/javascript; charset=utf-8"
      : pathname.endsWith(".d.ts")
      ? "text/plain; charset=utf-8"
      : pathname.endsWith(".css")
        ? "text/css; charset=utf-8"
        : pathname.endsWith(".png")
          ? "image/png"
          : pathname.endsWith(".webp")
            ? "image/webp"
          : pathname.endsWith(".svg")
            ? "image/svg+xml"
            : "application/octet-stream";

    res.writeHead(200, {
      "Content-Type": contentType,
      "Cache-Control": "no-store",
    });
    res.end(file);
  } catch {
    res.writeHead(404);
    res.end("Not found");
  }
}

async function serveAiosPublicAsset(req, res, assetPath = "") {
  const pathname = assetPath || new URL(req.url, `http://localhost:${port}`).pathname;
  const contentType = pathname.endsWith(".png")
    ? "image/png"
    : pathname.endsWith(".webp")
      ? "image/webp"
      : pathname.endsWith(".svg")
        ? "image/svg+xml"
        : pathname.endsWith(".jpg") || pathname.endsWith(".jpeg")
          ? "image/jpeg"
          : pathname.endsWith(".gif")
            ? "image/gif"
            : pathname.endsWith(".avif")
              ? "image/avif"
            : pathname.endsWith(".mp4")
              ? "video/mp4"
              : pathname.endsWith(".webm")
                ? "video/webm"
                : "application/octet-stream";

  for (const root of [aiosPublicRoot, packageRoot]) {
    const localPath = path.join(root, pathname);
    const normalized = path.normalize(localPath);

    if (!normalized.startsWith(root)) {
      continue;
    }

    try {
      const stat = await fs.stat(normalized);
      const supportsRanges = contentType.startsWith("video/") || contentType.startsWith("audio/");
      const baseHeaders = {
        "Content-Type": contentType,
        "Content-Length": stat.size,
        "Cache-Control": "no-store",
      };

      if (supportsRanges) {
        baseHeaders["Accept-Ranges"] = "bytes";
      }

      const rangeHeader = supportsRanges && typeof req.headers.range === "string" ? req.headers.range : "";
      const rangeMatch = rangeHeader.match(/^bytes=(\d*)-(\d*)$/);
      if (rangeMatch) {
        const [, rawStart, rawEnd] = rangeMatch;
        let start = rawStart ? Number(rawStart) : 0;
        let end = rawEnd ? Number(rawEnd) : stat.size - 1;

        if (!rawStart && rawEnd) {
          const suffixLength = Number(rawEnd);
          start = Number.isFinite(suffixLength) ? Math.max(stat.size - suffixLength, 0) : 0;
          end = stat.size - 1;
        }

        if (
          !Number.isInteger(start)
          || !Number.isInteger(end)
          || start < 0
          || end < start
          || start >= stat.size
        ) {
          res.writeHead(416, {
            "Content-Range": `bytes */${stat.size}`,
            "Cache-Control": "no-store",
          });
          res.end();
          return;
        }

        end = Math.min(end, stat.size - 1);
        res.writeHead(206, {
          ...baseHeaders,
          "Content-Length": end - start + 1,
          "Content-Range": `bytes ${start}-${end}/${stat.size}`,
        });
        if (req.method === "HEAD") {
          res.end();
        } else {
          createReadStream(normalized, { start, end }).pipe(res);
        }
        return;
      }

      res.writeHead(200, baseHeaders);
      if (req.method === "HEAD") {
        res.end();
      } else {
        createReadStream(normalized).pipe(res);
      }
      return;
    } catch {}
  }

  res.writeHead(404);
  res.end("Not found");
}

